{"command":"./.venv/bin/python3 - <<'EOF'
import json, collections
for name in ('debug','batch'):
    reused = collections.Counter(); sets = collections.Counter()
    with open(f'Resources/features/f-428/runs/P12.7/base-{name}.jsonl') as f:
        for line in f:
            r = json.loads(line)
            if not (r['auto'] and not r['correct']): continue
            sets[r['set']] += 1
            for a in r['atoms']:
                reused[(a['path'], a['reused'])] += 1
    print(name, 'sets:', dict(sets), 'path/reused:', dict(reused))
EOF","i":"Checking set values and reused flags"}

