		Console.WriteLine("      and site. TSV on stdout, relation x site summary on stderr.");
		Console.WriteLine();
		Console.WriteLine("  LetUsCook.AutoWrongCensus pairs <census.tsv> <trace.jsonl>");
		Console.WriteLine("      For each census row with blocker=window and route compound|other, emit the");
		Console.WriteLine("      parsedName head and the key head words.");
		Console.WriteLine();
		Console.WriteLine("Exits 1 on a missing input file or a trace whose set is not debug or batch.");
	}
}
