namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Runs one census or pairs invocation: reads the trace, classifies, writes TSV and the stderr summary.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Runs the invocation and returns the process exit code (0 success, 1 failure).</summary>
