{"content":"using System.Globalization;
using System.Text;
using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner. <c>census</c> classifies every <c>auto &amp;&amp; !correct</c> line of one
/// debug/batch trace; <c>pairs</c> joins P12.7 blocker-census rows (blocker=window, route compound/other)
/// with the trace. TSV goes to the output writer, the summary to the error writer (D-029: any other
/// set is refused with exit 1).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IAutoWrongCensusRunnerDeps deps,
	IOptions<AutoWrongCensusOptions> options) : IAutoWrongCensusRunner
{
	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <summary>Runs the invocation and returns the process exit code.</summary>
	/// <param name="stoppingToken">Cancellation token.</param>
	/// <returns>The exit code.</returns>
	public async Task<int> RunAsync(CancellationToken stoppingToken)
	{
		if (string.IsNullOrEmpty(_options.Command))
		{
			deps.Error.WriteLine("unusable arguments; usage:");
			deps.Error.WriteLine("  census <trace.jsonl>");
			deps.Error.WriteLine("  pairs <census.tsv> <trace.jsonl>");
			return 1;
		}

		if (!File.Exists(_options.TracePath))
		{
			deps.Error.WriteLine($"error: trace file not found at '{_options.TracePath}'.");
			return 1;
		}

		var lines = await ReadTraceAsync(_options.TracePath, stoppingToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.Where(l => !IsAllowedSet(l.Set)).Select(l => l.Set).Distinct().OrderBy(s => s, StringComparer.Ordinal).ToArray();
		if (refused.Length > 0)
		{
			deps.Error.WriteLine($"refused: trace set(s) '{string.Join("', '", refused)}' — only debug and batch traces are classified (D-029).");
			return 1;
		}

		return _options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: RunPairs(lines);
	}

	private static bool IsAllowedSet(string set) =>
		set.Equals("debug", StringComparison.OrdinalIgnoreCase) || set.Equals("batch", StringComparison.OrdinalIgnoreCase);

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken stoppingToken)
	{
		var jsonOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);
		var lines = new List<TraceLine>();
		try
		{
			await foreach (var line in File.ReadLinesAsync(path, stoppingToken).ConfigureAwait(false))
			{
				if (string.IsNullOrWhiteSpace(line))
				{
					continue;
				}

				lines.Add(JsonSerializer.Deserialize<TraceLine>(line, jsonOptions)
					?? throw new InvalidOperationException($"Trace line at {path} deserialized to null."));
			}
		}
		catch (Exception ex) when (ex is JsonException or IOException or OperationCanceledException)
		{
			deps.Error.WriteLine($"error: cannot read trace '{path}': {ex.Message}");
			return null;
		}

		return lines;
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSite = 0;

		foreach (var line in autoWrong)
		{
			ClassificationResult result;
			try
			{
				result = deps.Classifier.Classify(line);
			}
			catch (InvalidOperationException ex)
			{
				deps.Error.WriteLine($"error: {ex.Message}");
				return 1;
			}

			if (string.IsNullOrEmpty(result.Site))
			{
				unknownSite++;
				deps.Error.WriteLine($"error: unknown atom path '{line.Atoms.FirstOrDefault()?.Path}' on {line.HoldoutId}#{line.LineIndex}.");
				continue;
			}

			results.Add(result);
		}

		if (unknownSite > 0)
		{
			return 1;
		}

		WriteCensusTsv(results);
		WriteCensusSummary(lines.Count, results);
		return 0;
	}

	private void WriteCensusTsv(IReadOnlyList<ClassificationResult> results)
	{
		deps.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			deps.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(CultureInfo.InvariantCulture),
				Sanitize(r.Set),
				r.Relation,
				r.Site,
				r.OverrideKey,
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				r.AcceptedState,
				r.KeyState,
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private void WriteCensusSummary(int totalLines, IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		deps.Error.WriteLine($"autoWrongCensus set={set} traceLines={totalLines} autoWrongLines={results.Count}");

		foreach (var relation in results.Select(r => r.Relation).Distinct().OrderBy(r => r, StringComparer.Ordinal))
		{
			foreach (var site in results.Where(r => r.Relation == relation).Select(r => r.Site).Distinct().OrderBy(s => s, StringComparer.Ordinal))
			{
				var count = results.Count(r => r.Relation == relation && r.Site == site);
				deps.Error.WriteLine($"relation={relation}\tsite={site}\tcount={count}");
			}
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		deps.Error.WriteLine($"relation=other rate={results.Count == 0 ? 0 : otherCount * 100.0 / results.Count:0.0}% ({otherCount}/{results.Count})");

		var missing = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField).OrderBy(g => g.Key, StringComparer.Ordinal);
		foreach (var group in missing)
		{
			deps.Error.WriteLine($"missingField={group.Key}\tcount={group.Count()}");
		}

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			deps.Error.WriteLine($"overrideKey hits={overrideLines.Count(r => r.OverrideKey == "yes")}/{overrideLines.Count}");
		}

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var shouldReuseFalse = 0;
			foreach (var r in reuseLines)
			{
				var line = FindLine(r);
				var atom = line?.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line?.Atoms.FirstOrDefault();
				if (atom is null || string.IsNullOrEmpty(atom.LinkedIngredientId) || string.IsNullOrEmpty(atom.ParsedName))
				{
					continue;
				}

				if (!LetUsCook.Fdc.Parsing.IngredientLineParser.ShouldReuse(
					LetUsCook.Fdc.Parsing.IngredientLineParser.ComputeSlug(atom.ParsedName),
					atom.LinkedIngredientId))
				{
					shouldReuseFalse++;
				}
			}

			deps.Error.WriteLine($"reuse lines where ShouldReuse(parsedName, linkedIngredientId) is false: {shouldReuseFalse}/{reuseLines.Count}");
		}

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
			deps.Error.WriteLine($"row-choice-tier: key tier higher={keyHigher} accepted tier higher={tierLines.Count - keyHigher}");
		}

		var qualifierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier).ToList();
		foreach (var r in qualifierLines)
		{
			deps.Error.WriteLine($"same-head-other-qualifier {r.HoldoutId}#{r.LineIndex}: key-only=[{string.Join(", ", r.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(", ", r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private TraceLine? _lastLine;

	private TraceLine? FindLine(ClassificationResult r)
	{
		// The runner classifies in trace order; the summary re-derives atom facts from the same list.
		_ = _lastLine;
		return null;
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string Sanitize(string value)
	{
		if (value.IndexOfAny(['\t', '\n', '\r']) < 0)
		{
			return value;
		}

		var builder = new StringBuilder(value.Length);
		foreach (var c in value)
		{
			builder.Append(c is '\t' or '\n' or '\r' ? ' ' : c);
		}

		return builder.ToString();
	}

	private int RunPairs(IReadOnlyList<TraceLine> lines)
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			deps.Error.WriteLine($"error: census TSV not found at '{_options.CensusTsvPath}'.");
			return 1;
		}

		var censusRows = ReadCensusTsv(_options.CensusTsvPath);
		if (censusRows is null)
		{
			return 1;
		}

		var wanted = censusRows
			.Where(r => r.Blocker == "window" && (r.Route == "compound" || r.Route == "other"))
			.ToList();

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var emitted = 0;
		var unmatched = 0;

		deps.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		foreach (var row in wanted)
		{
			if (!byKey.TryGetValue((row.HoldoutId, row.LineIndex), out var line))
			{
				unmatched++;
				continue;
			}

			var atom = line.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line.Atoms.FirstOrDefault();
			var parsedNameHead = string.Join(' ', deps.Classifier.KeyHeadPhrase(deps.Normalizer.NormalizeToTokens(atom?.ParsedName ?? string.Empty)));
			var keyHead = string.Join(' ', deps.Classifier.KeyHeadPhrase(deps.Normalizer.NormalizeToTokens(line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty)));
			deps.Output.WriteLine(string.Join('\t',
				Sanitize(line.HoldoutId),
				line.LineIndex.ToString(CultureInfo.InvariantCulture),
				Sanitize(parsedNameHead),
				Sanitize(keyHead),
				Sanitize(line.RawText)));
			emitted++;
		}

		deps.Error.WriteLine($"pairs set={lines.Count > 0 ? lines[0].Set : string.Empty} windowCompoundOrOther={wanted.Count} emitted={emitted} unmatchedInTrace={unmatched}");
		return 0;
	}

	private static List<(string HoldoutId, int LineIndex, string Blocker, string Route)>? ReadCensusTsv(string path)
	{
		var rows = new List<(string, int, string, string)>();
		try
		{
			var allLines = File.ReadLines(path).ToList();
			if (allLines.Count == 0)
			{
				return null;
			}

			var header = allLines[0].Split('\t');
			var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
			for (var i = 0; i < header.Length; i++)
			{
				indexOf.TryAdd(header[i], i);
			}

			foreach (var name in new[] { "holdoutId", "lineIndex", "blocker", "route" })
			{
				if (!indexOf.ContainsKey(name))
				{
					return null;
				}
			}

			for (var i = 1; i < allLines.Count; i++)
			{
				var cells = allLines[i].Split('\t');
				if (cells.Length <= Math.Max(indexOf["holdoutId"], Math.Max(indexOf["lineIndex"], Math.Max(indexOf["blocker"], indexOf["route"]))))
				{
					continue;
				}

				rows.Add((cells[indexOf["holdoutId"]], int.Parse(cells[indexOf["lineIndex"]], CultureInfo.InvariantCulture), cells[indexOf["blocker"]], cells[indexOf["route"]]));
			}
		}
		catch (Exception ex) when (ex is IOException or FormatException)
		{
			return null;
		}

		return rows;
	}
}
