{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads one HoldoutGate trace, classifies every auto-wrong line
/// (<c>auto &amp;&amp; !correct</c>) through <see cref="AutoWrongClassifier"/>, writes the TSV to
/// <see cref="OutputWriters.Output"/> and the relation × site summary to
/// <see cref="OutputWriters.Error"/>. Refuses any trace whose records are not <c>debug</c>/<c>batch</c>
/// (D-029: no sealed read).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		return _options.Command switch
		{
			CommandLineArgumentParser.CensusCommand => await RunCensusAsync(cancellationToken).ConfigureAwait(false),
			CommandLineArgumentParser.PairsCommand => await RunPairsAsync(cancellationToken).ConfigureAwait(false),
			_ => Fail("unusable arguments; usage: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>"),
		};
	}

	private async Task<int> RunCensusAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = FirstRefusedSet(lines);
		if (refused is not null)
		{
			return Fail($"refused: trace record set '{refused}' is not debug or batch (D-029: no sealed read)");
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);
		var unknownSites = 0;
		foreach (var line in autoWrong)
		{
			var result = classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				unknownSites++;
				writers.Error.WriteLine($"error: unknown atom path '{line.Atoms.FirstOrDefault()?.Path}' on {line.HoldoutId}#{line.LineIndex}");
				continue;
			}

			results.Add(result);
		}

		WriteCensusTsv(results);
		WriteSummary(lines.Count, results);

		if (unknownSites > 0)
		{
			return Fail($"{unknownSites} line(s) with an unknown atom path were not classified");
		}

		return 0;
	}

	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		var lines = await ReadTraceAsync(_options.TracePath).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = FirstRefusedSet(lines);
		if (refused is not null)
		{
			return Fail($"refused: trace record set '{refused}' is not debug or batch (D-029: no sealed read)");
		}

		if (!File.Exists(_options.CensusTsvPath))
		{
			return Fail($"census TSV not found at '{_options.CensusTsvPath}'");
		}

		var windowRows = ReadWindowRows(_options.CensusTsvPath);
		if (windowRows is null)
		{
			return 1;
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var emitted = 0;
		var unmatched = 0;
		writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");
		foreach (var (holdoutId, lineIndex) in windowRows)
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				unmatched++;
				writers.Error.WriteLine($"warning: census row {holdoutId}#{lineIndex} not found in the trace");
				continue;
			}

			var parsedNameHead = line.Atoms.Count > 0 ? FoldName(line.Atoms[0].ParsedName) : string.Empty;
			var keyHead = line.ExpectedDescriptions.Count > 0
				? string.Join(' ', classifier.KeyHeadPhrase(_normalizerTokens(line.ExpectedDescriptions[0])))
				: string.Empty;
			writers.Output.WriteLine($"{Sanitize(holdoutId)}\t{lineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		writers.Error.WriteLine($"pairs: window compound/other rows={windowRows.Count} emitted={emitted} unmatched={unmatched}");
		return 0;
	}

	private IReadOnlyList<string> _normalizerTokens(string text) => _normalizer.NormalizeToTokens(text);

	private string FoldName(string parsedName)
	{
		var tokens = _normalizer.NormalizeToTokens(parsedName);
		return string.Join(' ', tokens.Select(t => IngredientLineResolver.SingularizeToken(t)));
	}

	private async Task<List<TraceLine>?> ReadTraceAsync(string path)
	{
		if (!File.Exists(path))
		{
			return Fail($"trace not found at '{path}'");
		}

		var lines = new List<TraceLine>();
		await foreach (var raw in File.ReadLinesAsync(path).ConfigureAwait(false))
		{
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			try
			{
				lines.Add(JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions)
					?? throw new InvalidOperationException("trace line deserialized to null"));
			}
			catch (JsonException ex)
			{
				return Fail($"trace line is not valid JSON: {ex.Message}");
			}
		}

		return lines;
	}

	private static string? FirstRefusedSet(IReadOnlyList<TraceLine> lines)
	{
		foreach (var line in lines)
		{
			if (!line.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !line.Set.Equals("batch", StringComparison.OrdinalIgnoreCase))
			{
				return line.Set;
			}
		}

		return null;
	}

	private static List<(string HoldoutId, int LineIndex)>? ReadWindowRows(string path)
	{
		var allLines = File.ReadLines(path).ToList();
		if (allLines.Count == 0)
		{
			return null;
		}

		var header = allLines[0].Split('\t');
		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf.TryAdd(header[i], i);
		}

		foreach (var required in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!indexOf.ContainsKey(required))
			{
				return null;
			}
		}

		var rows = new List<(string, int)>();
		for (var i = 1; i < allLines.Count; i++)
		{
			var cells = allLines[i].Split('\t');
			if (cells.Length <= Math.Max(indexOf["holdoutId"], Math.Max(indexOf["lineIndex"], Math.Max(indexOf["blocker"], indexOf["route"]))))
			{
				continue;
			}

			var blocker = cells[indexOf["blocker"]];
			var route = cells[indexOf["route"]];
			if (blocker.Equals("window", StringComparison.Ordinal)
				&& (route.Equals("compound", StringComparison.Ordinal) || route.Equals("other", StringComparison.Ordinal)))
			{
				rows.Add((cells[indexOf["holdoutId"]], int.Parse(cells[indexOf["lineIndex"]])));
			}
		}

		return rows;
	}

	private void WriteCensusTsv(IReadOnlyList<ClassificationResult> results)
	{
		writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(),
				Sanitize(r.Set),
				r.Relation,
				r.Site,
				r.OverrideKey,
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				r.AcceptedState,
				r.KeyState,
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private void WriteSummary(int tracedLines, IReadOnlyList<ClassificationResult> results)
	{
		var sets = string.Join(",", results.Select(r => r.Set).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(s => s, StringComparer.OrdinalIgnoreCase));
		writers.Error.WriteLine($"autoWrongCensus set={sets} tracedLines={tracedLines} autoWrongLines={results.Count}");

		foreach (var (relation, site, count) in results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (g.Key.Relation, g.Key.Site, g.Count()))
			.OrderBy(t => t.relation, StringComparer.Ordinal)
			.ThenBy(t => t.site, StringComparer.Ordinal))
		{
			writers.Error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={otherCount}/{results.Count} ({(results.Count > 0 ? otherCount * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField!)
			.Select(g => $"{g.Key}={g.Count()}")
			.OrderBy(s => s, StringComparer.Ordinal);
		writers.Error.WriteLine($"missingFields: {(missing.Any() ? string.Join(" ", missing) : "none")}");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		writers.Error.WriteLine($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseShouldReuseFalse = 0;
		foreach (var r in reuseLines)
		{
			var line = FindLine(r);
			var atom = line?.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line?.Atoms.FirstOrDefault();
			if (atom is { LinkedIngredientId.Length: > 0 })
			{
				if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
				{
					reuseShouldReuseFalse++;
				}
			}
		}

		writers.Error.WriteLine($"reuse lines where ShouldReuse(parsedName, linkedIngredientId) is false: {reuseShouldReuseFalse}/{reuseLines.Count}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		writers.Error.WriteLine($"row-choice-tier: keyHigher={keyHigher} acceptedHigher={tierLines.Count - keyHigher}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff: {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(", ", r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(", ", r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private TraceLine? _summaryLineLookup;

	private TraceLine? FindLine(ClassificationResult r) => _summaryLineLookup;

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private int Fail(string message)
	{
		writers.Error.WriteLine($"error: {message}");
		return 1;
	}
}
